    {
      "benefit": "IP",
      "years": [2018, 2019],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "A/E spikes to 1.33-1.44 (+0.40-0.50 above pre-2018 baseline of ~0.93), then reverts to ~0.91 in 2020",
      "confidence": 0.9,
      "evidence": [
        "artifacts/ae_ip_by_year.csv shows A/E jumping from 0.929 (2017) to 1.329 (2018) and 1.438 (2019), followed by a sharp drop to 0.914 (2020)",
        "Computed evidence pack confirms a 2018-2019 excursion with score 8.5 and onset ratio 1.12, indicating an abrupt single-year arrival of the spike rather than a gradual build-up"
      ],
      "recommended_action": "Investigate claims drivers in 2018-2019 (e.g., large group incidents, reporting/billing changes, or underwriting mix shifts). Determine if the spike was a one-off event requiring reserve tracking or if underlying incidence/severity assumptions need review. Monitor subsequent years for any residual level shift."
    }
  ]
}

